function onTime(){
 const videoTrack=tracks.find(t=>t.type==='video'&&!t.hidden);
 let i=videoTrack?.items.find(x=>x.id===playingItemId)||active();
 if(!i)return;
 const nextTime=Number(i.start)+Number(video.currentTime)-Number(i.sourceStart??0);
 if(nextTime>=Number(i.end)-.04){
  const next=videoTrack?.items.filter(x=>x.id!==i.id&&Number(x.start)>=Number(i.end)-.04).sort((a,b)=>Number(a.start)-Number(b.start))[0];
  if(next){
   playhead=Number(next.start);playingItemId=next.id;selected={trackId:videoTrack.id,itemId:next.id};
   syncPreview();
   const resume=()=>{if(playingItemId!==next.id||!video)return;syncPreview();video.play().then(()=>$('#cfNlePlay').textContent='Ⅱ').catch(err=>{const detail=video.error?.message||err?.message||'formato o archivo no disponible';say('No se pudo continuar la reproducción: '+detail);$('#cfNlePlay').textContent='▶';playingItemId=null;});};
   if(video.readyState>=2)resume();else video.addEventListener('loadedmetadata',resume,{once:true});
  }else{playhead=Number(i.end);playingItemId=null;video.pause();$('#cfNlePlay').textContent='▶';}
 }else playhead=Math.max(Number(i.start),nextTime);
 $('#cfNleTime').textContent=fmt(playhead);$('#cfNleSeek').value=playhead;overlay();
 const px=20*zoom;root?.querySelectorAll('.cf-nle-playhead').forEach(line=>line.style.left=(playhead*px)+'px');
}
function play(){
 const i=active();if(!i){say('Selecciona un clip de vídeo para reproducir.');return}
 if(video.paused){
  if(!video.currentSrc&&!video.src){say('Falta el vídeo original. Importa el MP4 desde Biblioteca de medios para volver a enlazarlo.');return}
  playingItemId=i.id;
  video.play().then(()=>$('#cfNlePlay').textContent='Ⅱ').catch(err=>{const detail=video.error?.message||err?.message||'formato o archivo no disponible';say('No se pudo reproducir el vídeo: '+detail);say('Comprueba que el MP4 original está importado y vuelve a enlazarlo.');playingItemId=null;$('#cfNlePlay').textContent='▶';});
 }else{video.pause();playingItemId=null;$('#cfNlePlay').textContent='▶'}
}
function editorKeydown(e){
 if(!root||root.hidden)return;
 const target=e.target;
 if(target?.closest?.('input,textarea,select,[contenteditable="true"]'))return;
 const mod=e.ctrlKey||e.metaKey,key=String(e.key||'').toLowerCase();
 if(mod){
  if(key==='c'){e.preventDefault();act('copy');return}
  if(key==='x'){e.preventDefault();act('copy');act('delete');return}
  if(key==='v'){e.preventDefault();act('paste');return}
  if(key==='z'){e.preventDefault();act(e.shiftKey?'redo':'undo');return}
  if(key==='y'){e.preventDefault();act('redo');return}
 }
 if(e.code==='Space'){e.preventDefault();play();return}
 if(!mod&&!e.altKey){
  if(key==='s'){e.preventDefault();act('split');return}
  if(key==='d'){e.preventDefault();act('duplicate');return}
  if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();act('delete');return}
 }
}
