function showClipMenu(x,y,trackId,itemId){
 const menu=$('#cfNleClipMenu');if(!menu)return;const track=tracks.find(t=>t.id===trackId),item=track?.items.find(i=>i.id===itemId);if(!track||!item)return;
 menu.replaceChildren();
 const add=(label,action,cls='')=>{const b=document.createElement('button');b.type='button';b.setAttribute('role','menuitem');b.textContent=label;if(cls)b.className=cls;const blocked=!!track.locked&&(action==='trimStart'||action==='trimEnd');if(blocked){b.disabled=true;b.title='La pista está bloqueada';}b.onclick=()=>{if(blocked)return;closeClipMenu();if(action==='seek'){playhead=Number(item.start);render();syncPreview();return;}if(action==='trimStart'||action==='trimEnd'){if(action==='trimStart'){const delta=playhead-Number(item.start);if(delta<=0||delta>=Number(item.end)-Number(item.start)){say('Coloca el cabezal dentro del fragmento.');return;}checkpoint();item.start=playhead;if(item.sourceStart!==undefined)item.sourceStart=Number(item.sourceStart)+delta;}else{if(playhead<=Number(item.start)||playhead>=Number(item.end)){say('Coloca el cabezal dentro del fragmento.');return;}checkpoint();item.end=playhead;}persist();render();syncPreview();return;}act(action);};menu.append(b);};
 add('Ir al inicio del fragmento','seek');menu.append(Object.assign(document.createElement('div'),{className:'separator'}));
 add('Dividir en el cabezal','split');add('Recortar inicio hasta aquí','trimStart');add('Recortar final hasta aquí','trimEnd');
 menu.append(Object.assign(document.createElement('div'),{className:'separator'}));add('Copiar fragmento','copy');add('Duplicar fragmento','duplicate');add('Eliminar fragmento','delete','danger');
 menu.style.left=Math.max(8,Math.min(x,window.innerWidth-210))+'px';menu.style.top=Math.max(8,Math.min(y,window.innerHeight-270))+'px';menu.hidden=false;
}
function addTrack(type){checkpoint();tracks.push({id:uid(),type,name:(type==='video'?'V':type==='audio'?'A':type==='subtitles'?'S':'T')+(tracks.filter(t=>t.type===type).length+1)+' · '+type,items:[],locked:false,muted:false,hidden:false});persist();render()}
function addText(){checkpoint();let t=tracks.find(x=>x.type==='text');if(!t){addTrack('text');t=tracks.find(x=>x.type==='text')}const i={id:uid(),kind:'text',start:playhead,end:playhead+3,text:'Nuevo texto',x:.5,y:.8,fontSize:48,color:'#ffffff'};t.items.push(i);selected={trackId:t.id,itemId:i.id};persist();render()}
function act(a){const f=sel();if(a==='zoomin'){zoom=Math.min(5,zoom*1.25);render();return}if(a==='zoomout'){zoom=Math.max(.25,zoom/1.25);render();return}if(a==='text'){addText();return}if(a==='copy'){if(f)clipboard={trackType:f.t.type,item:clone(f.i)};return}if(a==='paste'){if(!clipboard?.item)return;checkpoint();let t=tracks.find(x=>x.type===clipboard.trackType&&!x.locked);if(!t){t={id:uid(),type:clipboard.trackType,name:(clipboard.trackType==='video'?'V':clipboard.trackType==='audio'?'A':clipboard.trackType==='subtitles'?'S':'T')+(tracks.filter(x=>x.type===clipboard.trackType).length+1)+' · '+clipboard.trackType,items:[],locked:false,muted:false,hidden:false};tracks.push(t)}const duration=Math.max(.1,Number(clipboard.item.end)-Number(clipboard.item.start));const i={...clone(clipboard.item),id:uid(),start:playhead,end:playhead+duration};t.items.push(i);selected={trackId:t.id,itemId:i.id};persist();render();syncPreview();return}if(a==='undo'||a==='redo'){const from=a==='undo'?undoStack:redoStack,to=a==='undo'?redoStack:undoStack;if(!from.length)return;const current=JSON.stringify({tracks,selected,playhead});to.push(current);let snapshot=null;while(from.length&&!snapshot){const candidate=JSON.parse(from.pop());if(JSON.stringify(candidate)!==current)snapshot=candidate;}if(!snapshot)return;tracks=clone(snapshot.tracks);selected=snapshot.selected;playhead=snapshot.playhead;window.clipforgeBaseSetTracks?.(clone(tracks));persist();render();syncPreview();return}if(!f){say('Selecciona un elemento primero.');return}const {t,i}=f;const group=selectedItems.size>1?[...selectedItems].map(id=>{for(const track of tracks){const item=track.items.find(x=>x.id===id);if(item)return {t:track,i:item}}return null}).filter(Boolean):[{t,i}];if(group.some(x=>x.t.locked)){say('Hay una pista bloqueada en la selección.');return}checkpoint();if(a==='delete'){for(const x of group)x.t.items=x.t.items.filter(q=>q.id!==x.i.id);selected=null;selectedItems.clear();}if(a==='duplicate'){const ids=[];for(const x of group){const n={...clone(x.i),id:uid(),start:x.i.end+.2,end:x.i.end+.2+x.i.end-x.i.start};x.t.items.push(n);ids.push(n.id)}selectedItems=new Set(ids);selected={trackId:group[group.length-1].t.id,itemId:ids[ids.length-1]}}if(a==='split'){if(playhead<=i.start+.05||playhead>=i.end-.05){say('Coloca el cabezal dentro del clip para dividir.');return}const right={...clone(i),id:uid(),start:playhead};if(i.sourceStart!==undefined)right.sourceStart=Number(i.sourceStart)+playhead-i.start;i.end=playhead;t.items.push(right);selected={trackId:t.id,itemId:right.id}}persist();render()}
async function importFiles(files){let imported=0,relinked=0,storageFailures=[];for(const f of files){const url=URL.createObjectURL(f),type=f.type.startsWith('audio/')?'audio':f.type.startsWith('image/')?'image':'video';let d=5;if(type!=='image')d=await new Promise(resolve=>{const m=document.createElement(type);m.onloadedmetadata=()=>resolve(m.duration||5);m.onerror=()=>resolve(5);m.src=url});const a={id:uid(),name:f.name,type,url,duration:d};assets.push(a);try{await saveMedia(a.id,f)}catch(error){storageFailures.push(f.name);console.warn('ClipForge: medio solo disponible en esta sesión',f.name,error)}tracks.forEach(t=>t.items.forEach(item=>{if(item.missingAsset&&item.assetName===f.name){item.assetId=a.id;item.url=url;item.missingAsset=false;relinked++;}}));if(type==='video'&&sourceUrl===''){sourceUrl=url;try{await saveMedia('source',f)}catch(error){if(!storageFailures.includes(f.name))storageFailures.push(f.name);console.warn('ClipForge: vídeo fuente no persistido',error)}if(video){video.src=sourceUrl;video.load();}tracks.forEach(t=>t.items.forEach(item=>{if(item.assetId==='source'||item.missingAsset&&(!item.assetName||item.assetName===f.name)){item.assetId='source';item.url=sourceUrl;item.missingAsset=false;relinked++;}}));}let t=tracks.find(x=>x.type===(type==='image'?'video':type));if(!t){addTrack(type==='image'?'video':type);t=tracks.find(x=>x.type===(type==='image'?'video':type))}const i={id:uid(),kind:type,assetId:a.id,assetName:f.name,url,title:f.name,start:playhead,end:playhead+d,sourceStart:0};t.items.push(i);playhead+=type==='audio'?0:d;imported++}renderAssets();render();persist();const notes=['Medios importados: '+imported];if(relinked)notes.push(relinked+' referencias recuperadas');if(storageFailures.length)notes.push('No se pudieron guardar en el almacenamiento local: '+[...new Set(storageFailures)].join(', ')+'. Seguirán disponibles solo hasta cerrar/recargar esta sesión; conserva los originales.');say(notes.join(' · '));}
function renderAssets(){const e=$('#cfNleAssets');e.replaceChildren();assets.forEach(a=>{const b=document.createElement('button');b.className='cf-nle-asset';b.textContent=(a.type==='audio'?'♫ ':a.type==='image'?'▧ ':'▶ ')+a.name;b.onclick=()=>{const t=tracks.find(x=>x.type===(a.type==='image'?'video':a.type));const i={id:uid(),kind:a.type,assetId:a.id,url:a.url,title:a.name,start:playhead,end:playhead+a.duration,sourceStart:0};t.items.push(i);selected={trackId:t.id,itemId:i.id};render();persist()};e.append(b)})}
document.addEventListener('pointerdown',e=>{if(!e.target.closest?.('#cfNleClipMenu'))closeClipMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeClipMenu();});window.addEventListener('resize',closeClipMenu);window.addEventListener('scroll',closeClipMenu,true);window.addEventListener('clipforge:open-editor',open);
